// 4x4 Row-Major Transformation Matrix (VMatrix in client.dll @ 0x18256ad00)
struct VMatrix {
    float m[4][4]{0.0f};

    VMatrix() {
        m[0][0] = m[1][1] = m[2][2] = m[3][3] = 1.0f;
    }

    static VMatrix Multiply(const VMatrix& a, const VMatrix& b) {
        VMatrix out;
        for (int r = 0; r < 4; ++r) {
            for (int c = 0; c < 4; ++c) {
                out.m[r][c] = a.m[r][0] * b.m[0][c] +
                              a.m[r][1] * b.m[1][c] +
                              a.m[r][2] * b.m[2][c] +
                              a.m[r][3] * b.m[3][c];
            }
        }
        return out;
    }
};

