                  << " | Normal: (" << tr.normal.x << ", " << tr.normal.y << ", " << tr.normal.z << ")" << std::endl;

        // At y = -10, distance traveled = 20 units out of 60 -> frac = 20/60 = 0.3333...
        // Skin offset = 0.03125 / 60 = ~0.00052
