    // -------------------------------------------------------------------------
    // Test 5: BVH Spatial Acceleration Hierarchy (RnCompoundTree_t)
    // -------------------------------------------------------------------------
    totalTests++;
    std::cout << "\n[TEST 5] 48-byte SIMD BVH Spatial Acceleration Tree..." << std::endl;
    {
        cs2::RnCompoundTree tree;
